INSERT INTO perf_indicators_enb (id, en_name, cn_name, en_description, cn_description, group_id, operator_code, data_type, unit_id, updator, is_build_in, is_counter, arithmetic, statis_type, calculating_status, product_types, indicator_level, created_at, updated_at) VALUES ('C000060011', 'PDCP.UpOctDl', '小区用户面下行字节数', 'In the measurement period，summarize the cell user plane successful PDCP SDU bytes OTA, it is the PDCP SDU bytes send to lower layer, Classified statistics according to bearer QCI successfully sent defined as UE get the last segment ACK, MAC ACK for UM, RLC ACK for AM(3GPP TS 32.425) Note 1: this measurement not include handover Note 2: this measurement not inlcude retransmission', '在测量周期内，累加小区用户面通过空口成功发送的PDCP SDU字节数，即小区用户面PDCP层向下层发送的SDU字节数，并按照承载的QCI类型分类统计。成功发送定义为收到UE对PDCP SDU的最后一个分片的ACK确认，具体为UM模式下为MAC层ACK;AM模式下为RLC层ACK。字节数的统计在PDCP层，统计压缩之后的字节数。注1：该测量不包括切换过程中，通过X2或S1接口转发到其它eNB的PDCP SDU字节数。注2：该测量不考虑低层是否重传或传送失败。', 'c89c8327a43a4f4f9a39a3149e14e64f', NULL, '实数', 'KByte', 'admin', '1', '1', 'C000060011', 'sum', '', 'QRTB/BAIBLQ/BLX/BM/DXDF/RTS/RTD/CR-B4860/MLN/MLQ/QAFB/QAFA/QATA', 'device', '2018-03-31 00:00:00', '2018-03-31 00:00:00') ON CONFLICT (id) DO NOTHING;
