INSERT INTO perf_indicators_gnb (id, en_name, cn_name, en_description, cn_description, group_id, operator_code, data_type, unit_id, updator, is_build_in, is_counter, arithmetic, statis_type, calculating_status, created_at, updated_at) VALUES ('C010030006', 'PDCP.UpOctDl', '小区用户面下行PDCP PDU字节数', '', '在测量周期内，累加小区用户面成功发送的PDCP PDU字节数，即小区用户面PDCP层向下层发送的PDU字节数，并按照Flow的5QI类型分类统计。成功发送定义为收到底层或者F1接口 ACK确认，字节数的统计在PDCP层，统计压缩之后的字节数。注1：该测量不包括切换过程中，通过X2或Xn转发到其它gNB的PDCP PDU字节数。注2：该测量不考虑低层是否重传或传送失败。', 'fc7dd1f0a7f0389e060188837e4894dd', NULL, '浮点数', 'KByte', 'admin', '1', '1', 'C010030006', 'sum', '', '2021-12-08 00:00:00', '2021-12-08 00:00:00') ON CONFLICT (id) DO NOTHING;
