INSERT INTO perf_indicators_gnb (id, en_name, cn_name, en_description, cn_description, group_id, operator_code, data_type, unit_id, updator, is_build_in, is_counter, arithmetic, statis_type, calculating_status, created_at, updated_at) VALUES ('KGNB0101', 'KPI.RrcSuccConnRate', 'RRC连接建立成功率', 'When a UE in idle mode (RRC _ IDLE) receives a non-access layer request for a signaling connection, the UE initiates the RRC connection establishment process', '处于空闲模式（RRC_IDLE）下的UE收到非接入层请求建立信令连接时，UE将发起RRC连接建立过程', '3aa8d56f20205678977003cf6ab17081', NULL, '', '%', 'admin', '1', '0', 'C010070002/C010070001*100', 'pct', '', '2023-10-18 00:00:00', '2023-10-18 00:00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO perf_indicators_gnb (id, en_name, cn_name, en_description, cn_description, group_id, operator_code, data_type, unit_id, updator, is_build_in, is_counter, arithmetic, statis_type, calculating_status, created_at, updated_at) VALUES ('KGNB0102', 'KPI.FlowSuccConnRate', 'QoS Flow建立成功率', 'QoS Flow The success rate is the ratio of QoS Flow and the number of requests and QoS Flow', 'QoS Flow建立成功率用QoS Flow建立请求个数和QoS Flow建立成功个数的比表示', '3aa8d56f20205678977003cf6ab17081', NULL, '', '%', 'admin', '1', '0', 'C010080003/C010080001*100', 'pct', '', '2023-10-18 00:00:00', '2023-10-18 00:00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO perf_indicators_gnb (id, en_name, cn_name, en_description, cn_description, group_id, operator_code, data_type, unit_id, updator, is_build_in, is_counter, arithmetic, statis_type, calculating_status, created_at, updated_at) VALUES ('KGNB0103', 'KPI.NGSIG.SuccConnRate', 'NG接口UE相关逻辑信令连接建立成功率', 'The success rate of NG interface UE related logical signaling connection establishment is expressed by the ratio between the number of successful establishment of NG interface UE related logical signaling connection and the number of NG interface UE related logical signaling connection establishment requests', 'NG接口UE相关逻辑信令连接建立成功率用NG接口UE相关逻辑信令连接建立成功次数和NG接口UE相关逻辑信令连接建立请求次数之比表示', '3aa8d56f20205678977003cf6ab17081', NULL, '', '%', 'admin', '1', '0', 'C010110002/C010110001*100', 'pct', '', '2023-10-18 00:00:00', '2023-10-18 00:00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO perf_indicators_gnb (id, en_name, cn_name, en_description, cn_description, group_id, operator_code, data_type, unit_id, updator, is_build_in, is_counter, arithmetic, statis_type, calculating_status, created_at, updated_at) VALUES ('KGNB0104', 'KPI.WirelessSuccConnRate', '无线接通率', 'Considering the connection rate from a comprehensive perspective, the success rate of RRC connection establishment, the success rate of QoS Flow establishment and NG interface UE establishment are considered together', '从综合的角度考虑接通率，把RRC连接建立成功率、QoS Flow建立成功率和NG接口UE相关逻辑信令连接建立成功率联合起来考虑', '3aa8d56f20205678977003cf6ab17081', NULL, '', '%', 'admin', '1', '0', '(C010070002/C010070001)*(C010080003/C010080001)*(C010110002/C010110001)*100', 'pct', '', '2023-10-18 00:00:00', '2023-10-18 00:00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO perf_indicators_gnb (id, en_name, cn_name, en_description, cn_description, group_id, operator_code, data_type, unit_id, updator, is_build_in, is_counter, arithmetic, statis_type, calculating_status, created_at, updated_at) VALUES ('KGNB0301', 'KPI.WirelessDropRate.CellLevel', '无线掉线率（小区级）', 'UE CONTEXT Abnormal release ratio', 'UE CONTEXT异常释放比例', '3aa8d56f20205678977003cf6ab17081', NULL, '', '%', 'admin', '1', '0', '(C010060009-C010060010)/(C010060008+C010060011+C010090010+C010070013)*100', 'pct', '', '2023-10-18 00:00:00', '2023-10-18 00:00:00') ON CONFLICT (id) DO NOTHING;
